import {ingredients,recipes,exercises,sources} from './content.js';
import * as C from './core.js';
const KEY='afterhours.v1', $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=C.fresh(),storageError='',view=location.hash.slice(1)||'today',selectedDay='',mealTab='plan',undoState=null,draft=null,step=0,activeRecipe=null,recipeServings=1,session=null;
try{const raw=localStorage.getItem(KEY);if(raw)state=C.validateBackup(JSON.parse(raw));}catch(e){storageError='Your saved data could not be loaded. It has not been overwritten. Export the recovery file in Settings before starting again.';}
const icons={today:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',training:'<path d="m6 6 12 12M4 9l5-5m6 16 5-5M2 7l5-5m10 20 5-5"/>',meals:'<path d="M6 3v7m-3-7v5a3 3 0 0 0 6 0V3M6 11v10M17 3c-3 3-3 8 1 9V3h1v18"/>',progress:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 3 2 3v4l3 1 2 3 3-2 4 1 1-3 3-2-2-3 1-4-3-1-2-3z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',moon:'<path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',plus:'<path d="M12 5v14M5 12h14"/>',book:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3zM12 6v15"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.today}</svg>`;
const btn=(text,action,extra='',cls='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const money=n=>'₱'+Math.round(n).toLocaleString('en-PH');
const fmt=t=>{const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'pm':'am'}`;};
const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en',{weekday:'short',month:'short',day:'numeric',timeZone:'UTC'});
const today=()=>C.wakingDay(state.profile||C.defaults);
const day=()=>state.plan?.days.find(d=>d.day===(selectedDay||today()));
const doneWorkout=d=>state.workouts.find(w=>w.day===d);
const field=(label,name,value,type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const select=(label,name,value,options)=>`<label>${label}<select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;
const check=(label,name,checked,value='yes')=>`<label class="check"><input type="checkbox" name="${name}" value="${value}" ${checked?'checked':''}><span>${label}</span></label>`;
function toast(text,undo=false){$('#toast').innerHTML=`${esc(text)} ${undo?btn('Undo','undo','','text-btn'):''}`;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),8000);}
function save(text,fn){if(storageError){toast('Export your recovery file and reset storage before making changes.');return false;}const previous=structuredClone(state);try{fn?.();state.calendarRevision++;localStorage.setItem(KEY,JSON.stringify(state));undoState=previous;render();if(text)toast(text,true);return true;}catch(e){state=previous;toast('Could not save: '+e.message);return false;}}
function modal(html){const el=$('#modal');el.innerHTML=`<button class="close" data-action="close" aria-label="Close dialog">×</button>${html}`;if(!el.open)el.showModal();el.querySelector('h2')?.setAttribute('tabindex','-1');}
function close(){ $('#modal').close(); }
function week(){return state.plan?`<div class="week" aria-label="Waking days">${state.plan.days.map(d=>`<button data-action="day" data-day="${d.day}" class="${d.day===(selectedDay||today())?'selected':''}" aria-pressed="${d.day===(selectedDay||today())}"><span>${new Date(d.day+'T12:00Z').toLocaleDateString('en',{weekday:'short',timeZone:'UTC'})}</span><strong>${Number(d.day.slice(-2))}</strong><i class="${doneWorkout(d.day)?'complete':d.workout?'train':''}"></i></button>`).join('')}</div>`:'';}
function shell(content){const labels=['today','training','meals','progress','settings'];return `<aside class="sidebar"><a href="#today" class="brand"><span class="brand-mark">a</span>afterhours</a><div class="side-label">YOUR DAILY RHYTHM</div><nav>${labels.map(n=>`<a href="#${n}" class="${view===n?'active':''}">${icon(n)}<span>${n[0].toUpperCase()+n.slice(1)}</span>${view===n?'<b></b>':''}</a>`).join('')}</nav><div class="side-bottom"><div class="local-badge">${icon('moon')}<div>Built for your hours<small>Davao · Asia/Manila</small></div></div><div class="private-note">Your records stay on this device.<br>${navigator.onLine?'Local-first · No subscription':'Offline · Your records are available'}</div></div></aside><main><header class="topbar"><span>${view[0].toUpperCase()+view.slice(1)}</span><div><span class="zone">PHILIPPINE TIME</span><span class="avatar">${icon('moon')}</span></div></header><div class="page">${storageError?`<div class="notice danger">${storageError}</div>`:''}${content}</div><footer>One waking day at a time.<span>AFTERHOURS / LOCAL FIRST</span></footer></main>`;}
function title(kicker,title,sub,action=''){return `<div class="page-heading"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p class="muted">${sub}</p></div>${action}</div>`;}
function setupEmpty(){return `${title('YOUR FIRST CHAPTER','A routine that fits your hours.','Training, familiar meals, and a little more consistency.')}<div class="welcome-grid"><section class="hero"><div class="pill">${icon('moon')} YOUR NEXT ACTION</div><h2>Start with<br>your rhythm.</h2><p>Tell us about your equipment, food budget, and night-shift schedule. Review everything before your plan begins.</p>${btn('Set up my plan '+icon('arrow'),'setup','','primary lime')}<div class="hero-foot">About 5 minutes <span>•</span> No measurements required</div></section><section class="card setup-card"><p class="eyebrow">MADE FOR YOUR WAKING DAY</p><h2>The day starts<br>when you do.</h2><div class="rhythm-row"><span class="rhythm-icon">${icon('moon')}</span><div><strong>7–8 pm · Wake up</strong><p>Your preferred start</p></div></div><div class="rhythm-row"><span class="rhythm-icon">${icon('training')}</span><div><strong>Before 10 pm · Train</strong><p>Or use your 2–5 am backup window</p></div></div><div class="rhythm-row"><span class="rhythm-icon">${icon('clock')}</span><div><strong>Noon–2 pm · Wind down</strong><p>Protect your sleep and recovery</p></div></div><p class="small muted">Based on the schedule you provided. Exact times are yours to choose.</p></section></div><div class="section-head"><h2>A simple place for the essentials</h2><span class="muted">Nothing logged yet</span></div><div class="three-grid">${[['training','Train with what you have','Repeatable sessions, useful cues, and a record of every set.'],['meals','Cook within your budget','Filipino meals, complete recipes, and one grocery list.'],['progress','Notice what’s working','Weekly reviews that wait for enough data.']].map(([i,t,s])=>`<section class="card intro-card"><span class="intro-icon">${icon(i)}</span><h3>${t}</h3><p class="muted">${s}</p></section>`).join('')}</div>`;}
function todayPage(){if(!state.profile)return setupEmpty();const d=day(),p=state.profile,completed=d&&doneWorkout(d.day);if(!d)return `${title('YOUR WAKING DAY', 'Ready for your next week?', 'Your previous records are saved.')}<section class="card">${btn('Review next 7 days','renew','','primary')}</section>`;const logs=state.mealLogs.filter(x=>x.day===d.day),habits=state.habits[d.day]||{},xp=state.workouts.length*30+Object.values(state.habits).reduce((n,h)=>n+Object.values(h).filter(Boolean).length*10,0)+state.mealLogs.length*10;const t=state.plan.targets,totals=logs.reduce((a,m)=>{const n=m.nutrition||C.nutrition(C.recipe(m.recipe),m.servings,p);a.kcal+=n.kcal;a.protein+=n.protein;return a;},{kcal:0,protein:0});return `${title('WAKING DAY · '+dateLabel(d.day),'Make today count.','Your plan follows your rhythm, even past midnight.',btn(icon('plus')+' Check in','checkin','','outline'))}${week()}<div class="today-grid"><section class="hero compact"><div class="pill">${icon(completed?'check':d.workout?'training':'moon')} ${completed?'SESSION SAVED':d.workout?'YOUR NEXT SESSION':'RECOVERY DAY'}</div><h2>${completed?'Work done.<br>Room to recover.':d.workout?'A little stronger,<br>one set at a time.':'Recovery is<br>part of the plan.'}</h2><p>${d.workout?`${d.workout.duration} minutes · Full body · ${d.workout.light?'Lighter session':p.equipment.includes('dumbbell')?'Dumbbells & bodyweight':'Bodyweight'}`:'An easy walk, comfortable movement, and enough sleep. No strength session scheduled.'}</p><div class="hero-actions">${btn(completed?'View saved session '+icon('arrow'):d.workout?'Start workout '+icon('arrow'):'Log recovery '+icon('check'),completed?'history':d.workout?'start':'recovery',`data-day="${d.day}"`,'primary lime')}${d.workout&&!completed?btn('Change time','reschedule',`data-day="${d.day}"`,'ghost'):''}</div><div class="hero-foot">${icon('clock')} ${d.workout?fmt(d.workout.time)+' · '+esc(d.workout.note):'No timer. No lost streak.'}</div></section><section class="card daily-focus"><p class="eyebrow">TODAY’S FOCUS</p><h2>${t?'Fuel your session.':'Keep the basics simple.'}</h2><div class="fuel-number">${t?Math.round(totals.protein)+'<small> / '+t.protein+' g protein</small>':logs.length+'<small> / '+d.meals.length+' meals logged</small>'}</div><div class="bar"><span style="width:${Math.min(100,t?totals.protein/t.protein*100:logs.length/Math.max(1,d.meals.length)*100)}%"></span></div><p class="small muted">${t?Math.round(totals.kcal)+' / '+t.kcal+' estimated kcal · planned-meal logs only':'Habit-only mode. No calorie target needed.'}</p><div class="focus-tip">${icon('book')}<p>Prepare your next meal before the shift gets busy. Small routines save decisions later.</p></div>${btn('Log other food','food','','text-btn')}</section></div><div class="two-grid"><section class="card"><div class="section-head"><h2>On the menu</h2><a href="#meals">View plan ${icon('arrow')}</a></div>${d.meals.length?d.meals.map(m=>mealRow(m,d.day)).join(''):'<p class="notice">No recipes match all your restrictions. Review food preferences in Settings; restrictions will not be relaxed.</p>'}</section><section class="card"><div class="section-head"><h2>Daily essentials</h2><span class="tag">${Object.values(habits).filter(Boolean).length}/3</span></div>${[['water','Keep drinking water available'],['sleep','Protect my sleep window'],['recovery','Move or recover intentionally']].map(([id,label])=>`<button class="habit ${habits[id]?'checked':''}" data-action="habit" data-id="${id}" data-day="${d.day}"><span class="checkbox">${habits[id]?icon('check'):''}</span><span>${label}</span><small>+10 XP</small></button>`).join('')}${p.journey?`<div class="journey"><div><span class="eyebrow">YOUR JOURNEY</span><strong>${xp} XP <small>· ${xp>=660?'Steady rhythm':xp>=100?'Building momentum':'Getting started'}</small></strong></div><span class="journey-badge">${Math.floor(xp/100)+1}</span></div><p class="small muted">Day ${Math.max(1,Math.floor((Date.parse(d.day+'T12:00Z')-Date.parse(state.created))/86400000)+1)} of your optional 66-day journey · Continue afterward. Missed days never erase progress.</p>`:''}</section></div>`;}
function mealRow(m,d){const r=C.recipe(m.recipe),n=C.nutrition(r,m.servings,state.profile),done=state.mealLogs.some(l=>l.id===m.id);return `<div class="meal-row"><span class="meal-time">${fmt(m.time)}${C.mins(m.time)<C.mins(C.settingsFor(state.profile,d).wake)?'<small>next calendar day</small>':''}</span><div class="meal-detail"><button class="plain" data-action="recipe" data-id="${r.id}" data-servings="${m.servings}">${r.name}</button><p>${Math.round(n.kcal)} kcal · ${Math.round(n.protein)} g protein · ${money(n.cost)} <span class="small">est.</span></p></div>${btn(done?icon('check'):icon('plus'),'logmeal',`data-id="${m.id}" data-day="${d}" aria-label="${done?'Undo meal log':'Log '+r.name}"`,done?'circle checked':'circle')}</div>`;}
function trainingPage(){if(!state.profile)return setupEmpty();const p=state.profile,d=day(),r=C.routine(p,d?.workout?.light||d?.workout?.duration<25),last=state.workouts.at(-1);return `${title('STRENGTH, AT YOUR PACE','Your training room.','Repeat the basics. Keep the record. Build from there.',btn('Edit my routine','setup','','outline'))}${week()}<div class="training-banner"><div><span class="eyebrow">${d?.workout?'FULL BODY · '+fmt(d.workout.time):'RECOVERY DAY'}</span><h2>${d?.workout?`${d.workout.duration}-minute ${d.workout.light?'lighter':'strength'} session`:'Make space to recover'}</h2><p>${d?.workout?esc(d.workout.note):'Your next strength day is marked in the week above.'}</p></div><div class="button-row">${d?.workout&&!doneWorkout(d.day)?btn('Start session '+icon('arrow'),'start','','primary'):''}${d?.workout&&!doneWorkout(d.day)?btn(d.workout.light?'Use regular session':'Take it lighter','light','','outline'):''}</div></div>${last&&Date.parse((selectedDay||today())+'T12:00Z')-Date.parse(last.day+'T12:00Z')>14*86400000?'<p class="notice">Returning after a break? Use a lighter session and a comfortable load. Build back over several sessions.</p>':''}<div class="section-head"><h2>The movements</h2><span class="muted">5-minute warm-up included · gentle practice sets</span></div>${p.otherLimit?'<p class="notice danger">Your written limitation needs individual review. Automatic exercise selection is paused; the app cannot safely interpret medical or movement restrictions.</p>':''}${r.length?r.map((e,i)=>{const prev=C.previousPerformance(state.workouts,e.id);return `<section class="exercise-card"><span class="exercise-num">${String(i+1).padStart(2,'0')}</span><div class="exercise-main"><span class="eyebrow">${e.pattern}</span><h3>${e.name}</h3><p>${e.cues}</p><div class="exercise-meta"><span>${e.sets} sets × ${e.reps.join('–')} reps</span><span>${e.rest}s rest</span><span>${e.unit}</span></div><p class="small muted">Previous: ${prev?prev.sets.map(s=>`${s.reps} × ${s.weight} kg · effort ${s.rpe}`).join(' / '):'Your first session will set the baseline.'}</p></div></section>`;}).join(''):'<section class="card"><p>No compatible movements. Review equipment and limitations.</p></section>'}<details class="card"><summary>How progression works</summary><p>Choose a load that leaves about 2–3 repetitions in reserve (effort 7–8 out of 10). Once all saved sets reach the top of the rep range at effort 8 or less, the app suggests the next weight from your available list, respecting your minimum increment. Otherwise, repeat the load. Stop a movement if it hurts.</p><p>Lighter sessions use two sets. After a break, start comfortably and build back. Three nonconsecutive strength days are suggested; edit them during setup. Barbell work is not prescribed because this app cannot confirm rack, safeties, or spotter availability.</p></details><div class="section-head"><h2>Completed sessions</h2><span>${state.workouts.length} saved</span></div>${state.workouts.length?[...state.workouts].reverse().slice(0,20).map(w=>`<button class="history-row" data-action="history" data-day="${w.day}"><span>${icon('check')} Full body · ${dateLabel(w.day)}</span><span>${w.exercises.length} movements ${icon('arrow')}</span></button>`).join(''):'<p class="muted">Your completed sessions will appear here.</p>'}`;}
function mealsPage(){if(!state.profile)return setupEmpty();const p=state.profile,all=state.plan.days.flatMap(d=>d.meals),g=C.groceries(all,p,state.extraGroceries),purchase=g.reduce((n,x)=>n+x.purchase,0),consumed=g.reduce((n,x)=>n+x.consumed,0),over=purchase>p.budget;return `${title('GOOD FOOD. LESS GUESSWORK.','Your week, on a plate.','Familiar recipes, reusable ingredients, and a clear shopping list.',btn('Edit food preferences','setup','','outline'))}<div class="budget-strip"><div><span class="eyebrow">GROCERIES TO BUY</span><strong>${money(purchase)} <small>/ ${money(p.budget)} cap</small></strong></div><div><span class="eyebrow">PORTIONS CONSUMED</span><strong>${money(consumed)} <small>this week</small></strong></div><div class="${over?'budget-warning':'tag'}">${over?'Over budget by '+money(purchase-p.budget):'Within estimated budget'}</div></div><p class="small muted">Unverified planning prices, not live Davao prices. Packages purchased and food consumed differ. Pantry stock is deducted from purchases. Update prices in Settings.</p>${over?'<p class="notice danger">This menu exceeds your spending cap. Try economical mode, update pantry stock and actual prices, or change meals. The app will not reduce food portions simply to hide an overrun.</p>':''}<div class="tabs">${[['plan','7-day menu'],['grocery','Grocery list'],['recipes','Recipe library']].map(([id,t])=>btn(t,'meal-tab',`data-tab="${id}" aria-pressed="${mealTab===id}"`,mealTab===id?'selected':'')).join('')}</div>${mealTab==='plan'?`${week()}${day()?`<div class="section-head"><h2>${dateLabel(day().day)}</h2><span class="muted">${money(day().meals.reduce((a,m)=>a+C.nutrition(C.recipe(m.recipe),m.servings,p).cost,0))} · daily portions</span></div>${day().meals.map((m,i)=>{const r=C.recipe(m.recipe);return `<section class="card menu-card"><div class="recipe-monogram">0${i+1}</div><div><p class="eyebrow">${fmt(m.time)} · ${r.tag}</p><h2>${r.name}</h2><p class="muted">${r.time} min · ${m.servings} portion${m.servings!==1?'s':''} · ${Math.round(C.nutrition(r,m.servings,p).protein)} g protein, est.</p><div class="button-row">${btn('View recipe','recipe',`data-id="${r.id}" data-servings="${m.servings}"`,'outline')}${btn('Swap meal','swap',`data-id="${m.id}"`,'text-btn')}${btn('Time & portion','editmeal',`data-id="${m.id}"`,'text-btn')}</div></div></section>`;}).join('')||'<p class="notice">No compatible menu found. Change your constraints or seek a recipe verified for your restrictions. Unknown allergies pause menu generation.</p>'}`:''}<section class="card"><h3>Cook once, use it twice</h3><p class="muted">Adjacent days reuse recipes and ingredients. Scale a recipe to prepare extra portions, then refrigerate promptly or freeze. Only batch-cook when you have reliable cold storage; without a fridge, prepare each portion just before eating.</p><p class="small muted">Menus are approximate templates, not a guarantee of meeting nutrient needs. Review daily calories and protein against your optional targets.</p></section>`:mealTab==='grocery'?`<section class="card"><div class="section-head"><h2>One consolidated list</h2>${btn('Copy list','copygroceries','','outline')}</div><p class="muted">All seven days + recipes you added. Stock quantities are raw edible grams. Package weights should match the edible or drained basis.</p><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>For recipes</th><th>Pantry used</th><th>Buy</th><th>Cost</th></tr></thead><tbody>${g.map(x=>`<tr><td>${x.name}</td><td>${Math.round(x.grams)} g</td><td>${Math.round(x.pantry)} g</td><td>${x.packages} × ${x.pack} g</td><td>${money(x.purchase)}</td></tr>`).join('')}</tbody></table></div>${state.extraGroceries.length?btn('Clear extra recipe additions','clearextra','','text-btn'):''}</section>`:`<div class="recipe-grid">${C.allowedRecipes(p).map(r=>`<section class="card"><div class="section-head"><span class="tag">${r.tag}</span>${state.favorites.includes(r.id)?'<span>★ Saved</span>':''}</div><h2>${r.name}</h2><p class="muted">${r.time} min · ${Math.round(C.nutrition(r).kcal)} kcal · ${money(C.nutrition(r,1,p).cost)} est.</p>${btn('Open recipe '+icon('arrow'),'recipe',`data-id="${r.id}"`,'text-btn')}</section>`).join('')||'<p class="notice">No recipe matches the current restrictions.</p>'}</div>`}`;}
function chart(){const cs=state.checkins.filter(c=>c.weight).slice(-30);if(cs.length<2)return `<div class="empty-chart"><div class="chart-lines"></div><p>${cs.length?'One weigh-in saved. Add another to see your trend.':'Your trend starts with your first check-in.'}</p><span>No sample weights or invented progress.</span></div>`;const vals=cs.map(c=>c.weight),lo=Math.min(...vals)-.5,hi=Math.max(...vals)+.5,coords=vals.map((v,i)=>[40+i*560/(vals.length-1),170-(v-lo)/(hi-lo)*130]);return `<svg class="weight-chart" viewBox="0 0 640 210" role="img" aria-label="Weight chart from ${cs[0].weight} to ${cs.at(-1).weight} kilograms"><path d="M40 40H600M40 105H600M40 170H600" stroke="#e1e5e0" fill="none"/><polyline points="${coords.map(c=>c.join(',')).join(' ')}" stroke="#49745a" stroke-width="3" fill="none"/>${coords.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4" fill="#49745a"><title>${cs[i].day}: ${vals[i]} kg</title></circle>`).join('')}<text x="40" y="200">${cs[0].day}</text><text x="510" y="200">${cs.at(-1).day}</text><text x="0" y="40">${hi.toFixed(1)}</text><text x="0" y="170">${lo.toFixed(1)}</text></svg>`;}
function progressPage(){if(!state.profile)return setupEmpty();const r=C.weeklyReview(state,today()),xp=state.workouts.length*30+state.mealLogs.length*10+Object.values(state.habits).reduce((n,h)=>n+Object.values(h).filter(Boolean).length*10,0);return `${title('LOOK AT THE LONG GAME','Progress, without the pressure.','Patterns matter more than a perfect day.',btn(icon('plus')+' Check in','checkin','','primary'))}<div class="stats"><section class="card"><span class="eyebrow">SESSIONS COMPLETED</span><strong>${state.workouts.length}</strong><p>Every session is saved.</p></section><section class="card"><span class="eyebrow">DAYS WITH A CHECK-IN</span><strong>${state.checkins.length}</strong><p>Weight is always optional.</p></section><section class="card"><span class="eyebrow">${state.profile.journey?'JOURNEY XP':'MEALS LOGGED'}</span><strong>${state.profile.journey?xp:state.mealLogs.length}</strong><p>${state.profile.journey?'Recovery earns progress, too.':'No missing meal counted as zero.'}</p></section></div><div class="two-grid"><section class="card"><div class="section-head"><h2>Weight over time</h2><span class="tag">kg · optional</span></div>${chart()}<details><summary>View weigh-ins</summary>${state.checkins.filter(c=>c.weight).map(c=>`<p>${c.day} · ${c.weight} kg</p>`).join('')||'<p>No weigh-ins yet.</p>'}</details></section><section class="card"><p class="eyebrow">WEEKLY REVIEW</p><h2>${r.title}</h2><p>${r.text}</p>${r.delta?`<div class="button-row">${btn('Accept +100 kcal','acceptreview','','primary')}${btn('Keep current target','declinereview','','outline')}</div>`:'<span class="tag">No automatic target change</span>'}<p class="small muted">Training: ${state.workouts.filter(w=>w.day>=C.addDays(today(),-6)).length} sessions this week. Food completeness is marked separately in food logging.</p>${state.review.at(-1)?`<p class="small">Last decision: ${esc(state.review.at(-1).decision)} · ${state.review.at(-1).day}</p>`:''}</section></div><section class="card"><div class="section-head"><h2>A little reflection</h2><span class="muted">Private journal</span></div><form id="journal-form"><label class="sr-only" for="journal-text">Journal entry</label><textarea id="journal-text" name="text" rows="3" maxlength="10000" required placeholder="What helped today? What would make tomorrow easier?"></textarea><div class="form-foot"><span class="small muted">Saved only on this device.</span><button class="primary" type="submit">Save note</button></div></form>${[...state.journal].reverse().slice(0,8).map(j=>`<article class="journal-entry"><span class="eyebrow">${dateLabel(j.day)}</span><p>${esc(j.text)}</p></article>`).join('')}</section>`;}
function settingsPage(){return `${title('MAKE IT YOURS','Your preferences. Your data.','Everything personal is stored on this device.')}<div class="settings-grid"><section class="card"><h2>Personal plan</h2><p>Schedule, training equipment, food restrictions, nutrition mode, and budget.</p>${btn(state.profile?'Edit setup & review plan':'Set up my plan','setup','','primary')}${state.profile?`<div class="settings-summary"><span>${state.profile.nutrition==='habits'?'Habit-only':'Estimated nutrition'} mode</span><span>${money(state.profile.budget)} / week</span><span>${state.profile.minutes}-minute sessions</span></div>`:''}</section><section class="card"><h2>Backup & transfer</h2><p>There is no automatic sync. Export a backup and import it on your other device. A backup contains your personal records; keep it private.</p><div class="button-row">${btn('Export backup','export','','outline')}<label class="button outline">Import backup<input id="import-file" type="file" accept=".json,application/json" hidden></label></div>${storageError?btn('Export unreadable recovery file','recoveryexport','','text-btn'):''}<p class="small muted">Import validates the file, then asks before replacing records. Browser data clearing or storage eviction can remove local records.</p>${btn('Request persistent storage','persist','','text-btn')}</section><section class="card"><h2>Reminders</h2><span class="status-warn">Background push: not connected</span><p>OneSignal offers a free web-push plan, but an account and a secure server-side scheduling connection are not configured. No background push reminders are currently scheduled.</p><p>Calendar alerts are available now. They can fire while this app is closed. Import into a dedicated “Afterhours” calendar; remove its old events before importing a revised schedule to prevent duplicates.</p>${state.profile?`<div class="button-row">${btn('Reminder settings','reminders','','outline')}${btn('Download calendar alerts','calendar','','primary')}</div>`:''}<div class="button-row">${btn('Test device notification','testnotification','','text-btn')}</div><p class="small muted" id="notification-status">Permission: ${'Notification'in window?Notification.permission:'unavailable in this browser'}. The test is immediate, not a scheduled background-delivery test. iPhone web notifications require installation on the Home Screen. Internet, browser permission, and Focus settings affect push delivery; timing is not guaranteed.</p></section><section class="card"><h2>Install Afterhours</h2><ol><li><strong>iPhone:</strong> Open the hosted link in Safari. Open Share, choose Add to Home Screen, then Add.</li><li><strong>Mac:</strong> Open the link in Safari. Choose File → Add to Dock.</li><li>Open once while online to cache the app. Check offline access before relying on it.</li></ol><p class="small muted">${'serviceWorker'in navigator?'Offline cache supported in this browser.':'Offline cache unavailable in this browser.'} <span id="offline-status"></span></p></section></div>${state.profile?`<section class="card"><div class="section-head"><h2>Pantry & local prices</h2><span class="tag">PHP · grams</span></div><p class="muted">Starting prices are illustrative placeholders, not verified market quotes. Enter the package price and edible/drained package size from your receipt. Pantry stock reduces the grocery list.</p><form id="prices-form"><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Pantry g</th><th>Package g</th><th>Package ₱</th><th>Source / date</th></tr></thead><tbody>${Object.entries(ingredients).map(([id,i])=>{const pr=state.profile.prices[id];return `<tr><td>${i.name}</td><td><input aria-label="${i.name} pantry grams" name="pantry-${id}" type="number" min="0" max="100000" value="${state.profile.pantry[id]||0}"></td><td><input aria-label="${i.name} package grams" name="pack-${id}" type="number" min="1" max="100000" value="${pr?.pack||i.pack}"></td><td><input aria-label="${i.name} package pesos" name="price-${id}" type="number" min="0" max="100000" step=".01" value="${pr?.price??i.price}"></td><td><input aria-label="${i.name} price source" name="source-${id}" value="${esc(pr?.source||'Unverified planning estimate')}"><small>${pr?.date||'No observed date'}</small></td></tr>`;}).join('')}</tbody></table></div><button class="primary" type="submit">Save stock & prices</button></form></section>`:''}<details class="card"><summary>Planning rules, sources & limitations</summary><p>All times use Asia/Manila. A waking day begins at your chosen wake time. Overnight meals belong to that day. Workouts use three suggested nonconsecutive days and your verified equipment; the same session moves to 02:30 when it does not fit before work. Recovery days are intentional.</p><p>Optional adult energy estimate: Mifflin–St Jeor resting energy = 10 × kg + 6.25 × cm − 5 × age + sex coefficient (+5 or −161), multiplied by your selected activity factor. Fat-loss preference uses a modest 10% starting reduction. Protein reference: 1.6 g/kg. These are rough starting estimates, not measured needs; no automatic calorie cuts.</p><p>PhilFCT is the preferred Philippine reference, but direct nutrient records were not available for verified extraction. Bundled generic ingredient estimates are explicitly not represented as PhilFCT-derived values. Prices are placeholders. Check product labels for allergens and cross-contact; the app cannot verify brands. Unknown allergy notes pause menu generation.</p><p>App files and bundled recipes can be exposed through hosting; personal records are never embedded in published files. No analytics, paid API, or subscription is required by the app. Free hosting and push providers may change their terms or availability. This build has no active push service.</p><ul>${sources.map(([t,u])=>`<li><a href="${u}" target="_blank" rel="noreferrer">${t}</a></li>`).join('')}</ul><p class="small muted">References checked September 21, 2026. Personal medical needs, pregnancy, eating-disorder recovery, or other clinical nutrition concerns require individualized care; habit-only mode avoids numerical targets.</p></details><section class="card danger-zone"><h3>Delete local records</h3><p>This affects this browser only. Export first if you want to keep a copy.</p>${btn('Delete my data','delete','','danger-button')}</section>`;}
function render(){if(!['today','training','meals','progress','settings'].includes(view))view='today';$('#app').innerHTML=shell(({today:todayPage,training:trainingPage,meals:mealsPage,progress:progressPage,settings:settingsPage}[view])());}
function setup(){const p=draft,days=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];const contents=[
`<p class="muted">Choose a starting point. These preferences stay on this device, and you can change them later.</p><div class="form-grid">${select('Your main priority','goal',p.goal,['consistency','fat loss','build muscle'])}${select('Training experience','experience',p.experience,['beginner','returning','experienced'])}${select('Session length','minutes',p.minutes,[[20,'20 minutes'],[35,'35 minutes'],[45,'45 minutes'],[60,'60 minutes']])}${select('Nutrition approach','nutrition',p.nutrition,[['habits','Habits only — no measurements'],['estimates','Optional calorie & protein estimates']])}</div><details ${p.nutrition==='estimates'?'open':''}><summary>Optional personal measurements</summary><p class="small muted">Age, weight, height, and an equation coefficient help estimate adult energy needs. They are optional; leaving them blank keeps you in habit-only planning. This equation is not a measurement of your metabolism.</p><div class="form-grid">${field('Age (18+ for estimates)','age',p.age,'number','min="18" max="100"')}${field('Weight (kg)','weight',p.weight,'number','min="30" max="300" step=".1"')}${field('Height (cm)','height',p.height,'number','min="120" max="230"')}${select('Equation coefficient','sex',p.sex,[['','Do not estimate'],['female','Female coefficient (−161)'],['male','Male coefficient (+5)']])}${select('Activity outside workouts','activity',p.activity,[[1.2,'Mostly sitting'],[1.4,'Lightly active'],[1.6,'Moderately active']])}</div></details>${check('Use the optional 66-day journey and XP','journey',p.journey)}`,
`<p class="muted">Times below are suggestions based on your night shift. Confirm your exact routine. All times are Philippine time.</p><label>Workdays (day your shift starts)</label><div class="daychecks">${days.map((d,i)=>check(d,'workdays',p.workdays.includes(i),i)).join('')}</div><div class="form-grid">${field('Wake on workdays','wake',p.wake,'time','required')}${field('Sleep on workdays','sleep',p.sleep,'time','required')}${field('Shift starts','workStart',p.workStart,'time','required')}${field('Shift ends','workEnd',p.workEnd,'time','required')}${field('Preparation before work (minutes)','prep',p.prep,'number','min="0" max="180" required')}${field('Preferred workday workout','workout',p.workout,'time','required')}${field('Wake on days off','offWake',p.offWake,'time','required')}${field('Sleep on days off','offSleep',p.offSleep,'time','required')}${field('Day-off workout','offWorkout',p.offWorkout,'time','required')}</div><label>Strength days</label><div class="daychecks">${days.map((d,i)=>check(d,'trainDays',p.trainDays.includes(i),i)).join('')}</div><p class="small muted">Choose 2–3 nonconsecutive days to leave recovery time. If the preferred session cannot fit, the same session moves to 02:30.</p>`,
`<p class="muted">Confirm what you can safely use. No equipment is assumed until you select it.</p>${check('I have dumbbells','dumbbell',p.equipment.includes('dumbbell'))}<div class="form-grid">${select('Bench type','bench',p.bench,[['none','No confirmed bench'],['flat','Stable flat bench'],['adjustable','Stable adjustable bench']])}${select('Barbell available?','barbell',p.barbell?'yes':'no',[['no','No / not confirmed'],['yes','Yes']])}${field('Available dumbbell weights (kg, per dumbbell)','weights',p.weights,'text','placeholder="e.g. 2, 4, 6, 8, 10"')}${field('Smallest weight increase (kg)','increment',p.increment,'number','min=".25" max="20" step=".25" required')}</div><p class="small muted">Barbell availability is recorded, but barbell bench pressing is excluded until rack and safety support can be verified. Bodyweight movements remain available.</p><label>Movement limitations to avoid</label><div class="check-grid">${['knee','back','shoulder','wrist'].map(l=>check(l[0].toUpperCase()+l.slice(1),'limitations',p.limitations.includes(l),l)).join('')}</div>${field('Other limitations (optional)','otherLimit',p.otherLimit,'text','maxlength="500"')}<p class="small muted">A written limitation pauses automatic exercise selection because it needs individual review. Never train through pain.</p>`,
`<div class="form-grid">${field('Weekly grocery cap (₱)','budget',p.budget,'number','min="0" max="100000" required')}${select('Menu approach','style',p.style,[['economical','Economical · lowest-cost rotation'],['balanced','Balanced cost · more variety'],['convenience','Convenience · faster preparation']])}${select('Food preference','diet',p.diet,[['any','No dietary preference'],['vegetarian','Vegetarian (eggs allowed)']])}${field('Maximum recipe time (minutes)','prepTime',p.prepTime,'number','min="5" max="180" required')}</div><label>Allergies / ingredients to exclude</label><div class="check-grid">${['egg','soy','fish','gluten','legume','milk','peanut','tree nut','shellfish','sesame'].map(a=>check(a,'allergies',p.allergies.includes(a),a)).join('')}</div>${field('Other allergy (pauses automated menus)','otherAllergy',p.otherAllergy,'text','maxlength="500"')}${field('Ingredients to avoid (comma-separated names)','avoid',p.avoid,'text','placeholder="e.g. banana, sardine" maxlength="500"')}<label>Cooking and storage equipment</label><div class="check-grid">${['stove','rice cooker','microwave','fridge'].map(k=>check(k,'kitchen',p.kitchen.includes(k),k)).join('')}</div><details><summary>Pantry stock I already have</summary><div class="form-grid">${Object.entries(ingredients).map(([id,i])=>field(i.name+' (raw edible g)','stock-'+id,p.pantry[id]||0,'number','min="0" max="100000"')).join('')}</div></details>`,
`<p class="muted">Set times when you can actually eat. After-midnight meals stay in the same waking day. These are editable suggestions, not confirmed work breaks.</p><div class="form-grid">${p.meals.map((t,i)=>field('Workday meal '+(i+1),'meal'+i,t,'time','required')).join('')}${p.offMeals.map((t,i)=>field('Day-off meal '+(i+1),'offmeal'+i,t,'time','required')).join('')}</div><h3>Quiet hours</h3><div class="form-grid">${field('Silence from','quietStart',p.quietStart,'time','required')}${field('Until','quietEnd',p.quietEnd,'time','required')}</div><p class="small muted">Reminders during quiet hours or your sleep window are omitted. Scheduled background push is not connected; downloadable calendar alerts are available after setup.</p>`
];if(step===5){const preview=C.buildPlan(p,C.wakingDay(p),state.plan,state.workouts),g=C.groceries(preview.days.flatMap(d=>d.meals),p),cost=g.reduce((a,x)=>a+x.purchase,0),r=C.routine(p);modal(`<p class="eyebrow">STEP 6 OF 6 · YOUR PLAN</p><h2>Make it your own.</h2><p class="muted">Nothing starts until you accept. Use Back to change your preferences.</p><div class="review-summary"><div><span>Training</span><strong>${p.trainDays.length} days · ${r.length} movements · ${p.minutes} min</strong></div><div><span>Nutrition</span><strong>${preview.targets?`${preview.targets.kcal} kcal · ${preview.targets.protein} g protein (est.)`:'Habit-only · no numerical targets'}</strong></div><div><span>Groceries to buy</span><strong>${money(cost)} / ${money(p.budget)} estimated cap</strong></div></div>${cost>p.budget?`<p class="notice danger">Menu exceeds your cap by ${money(cost-p.budget)}. It is not a budget-feasible plan yet.</p>`:''}${!C.allowedRecipes(p).length?'<p class="notice danger">No recipes meet all restrictions. Your meal plan will remain empty until constraints are reviewed.</p>':''}${!r.length?'<p class="notice danger">Automatic exercise selection is paused. Review movement limitations.</p>':''}<div class="review-days">${preview.days.map(d=>`<div><strong>${dateLabel(d.day)}</strong><span>${d.workout?'Train '+fmt(d.workout.time)+' · '+d.workout.duration+' min':'Recovery'}</span><small>${d.meals.map(m=>fmt(m.time)).join(' / ')}</small></div>`).join('')}</div><p class="small muted">Meal estimates may not meet your exact targets. Portions are adjusted in quarter-serving steps, with a cap of 2.5 servings. Review meals after starting. Completed history is preserved when plans change.</p><div class="form-foot">${btn('Back','setup-back','','outline')}${btn('Accept & save my plan','acceptplan','','primary')}</div>`);return;}
modal(`<p class="eyebrow">STEP ${step+1} OF 6 · ${['STARTING POINT','YOUR SCHEDULE','YOUR EQUIPMENT','FOOD & BUDGET','MEAL BREAKS'][step]}</p><div class="step-progress">${Array.from({length:6},(_,i)=>`<i class="${i<=step?'filled':''}"></i>`).join('')}</div><h2>${['Let’s find your starting point.','Work with your body clock.','Your own training room.','Food that works for you.','A place for every meal.'][step]}</h2><form id="setup-form">${contents[step]}<p id="setup-error" class="error" role="alert"></p><div class="form-foot">${step?btn('Back','setup-back','','outline'):'<span class="small muted">Private · local to this device</span>'}<button class="primary" type="submit">${step===4?'Review my plan':'Continue'} ${icon('arrow')}</button></div></form>`);}
function readSetup(form){const f=new FormData(form),p=draft,get=n=>f.get(n),all=n=>f.getAll(n);if(step===0){for(const n of ['goal','experience','nutrition','sex'])p[n]=get(n);for(const n of ['minutes','activity'])p[n]=Number(get(n));for(const n of ['age','height','weight'])p[n]=get(n)?Number(get(n)):null;p.journey=f.has('journey');}
if(step===1){for(const n of ['wake','sleep','offWake','offSleep','workStart','workEnd','workout','offWorkout'])p[n]=get(n);p.prep=Number(get('prep'));p.workdays=all('workdays').map(Number);p.trainDays=all('trainDays').map(Number);if(p.trainDays.length>3||p.trainDays.some(d=>p.trainDays.includes((d+1)%7)))throw Error('Choose up to 3 strength days with a recovery day between sessions.');if(p.wake===p.sleep||p.offWake===p.offSleep)throw Error('Wake and sleep times must differ.');}
if(step===2){p.equipment=f.has('dumbbell')?['dumbbell']:[];p.bench=get('bench');p.barbell=get('barbell')==='yes';p.weights=get('weights');p.increment=Number(get('increment'));p.limitations=all('limitations');p.otherLimit=get('otherLimit').trim();if(p.equipment.includes('dumbbell')&&(!p.weights.trim()||p.weights.split(',').some(x=>!Number(x)||Number(x)<0||Number(x)>200)))throw Error('List your available dumbbell weights as positive kg values separated by commas.');}
if(step===3){p.budget=Number(get('budget'));p.style=get('style');p.diet=get('diet');p.prepTime=Number(get('prepTime'));p.allergies=all('allergies');p.kitchen=all('kitchen');p.otherAllergy=get('otherAllergy').trim();p.avoid=get('avoid');for(const id of Object.keys(ingredients))p.pantry[id]=Number(get('stock-'+id));}
if(step===4){p.meals=[0,1,2].map(i=>get('meal'+i));p.offMeals=[0,1,2].map(i=>get('offmeal'+i));p.quietStart=get('quietStart');p.quietEnd=get('quietEnd');for(const [ts,s]of [[p.meals,{wake:p.wake,sleep:p.sleep}],[p.offMeals,{wake:p.offWake,sleep:p.offSleep}]])if(ts.some(t=>C.isAsleep(t,s)))throw Error('A meal falls inside your sleep window. Choose a time while awake or edit your schedule.');}}
function showRecipe(id,n=1){activeRecipe=C.recipe(id);recipeServings=n;const r=activeRecipe,p=state.profile||C.defaults,t=C.nutrition(r,n,p);modal(`<p class="eyebrow">${r.tag} · ${r.prep} MIN PREP / ${r.cook} MIN COOK</p><h2>${r.name}</h2><div class="recipe-tools"><label>Servings<input id="recipe-servings" type="number" min=".25" max="10" step=".25" value="${n}"></label><span>${Math.round(t.kcal)} kcal · ${Math.round(t.protein)} g protein<br>${money(t.cost)} total · estimates</span></div><h3>What you’ll need</h3><p class="small muted">Raw edible grams unless labeled. Rice and mung beans are dry weights; canned tuna is drained. Household measures are approximate and scale with the recipe.</p><ul class="ingredients">${Object.entries(r.items).map(([id,g])=>`<li><strong>${+(g*n).toFixed(1)} g</strong><span>${ingredients[id].name}<small>${C.household(id,g*n)}</small></span></li>`).join('')}</ul><p class="small muted">Water as directed; optional pinch of salt. When batch cooking, use enough water for the scaled grains and keep the stew consistency similar.</p><h3>Let’s cook</h3><ol class="steps">${C.scaledSteps(r,n).map(s=>`<li>${s}</li>`).join('')}</ol><h3>Substitutions</h3><p>${r.subs} Use a meal swap for recalculated totals; informal substitutions change estimates.</p><h3>Keep it safely</h3><p>${r.storage}</p><p class="small muted">Per standard serving: ${Math.round(C.nutrition(r,1,p).kcal)} kcal · ${Math.round(C.nutrition(r,1,p).protein)} g protein · ${money(C.nutrition(r,1,p).cost)}. Nutrition and prices are estimates.</p><div class="button-row">${btn('Copy complete recipe','copyrecipe','','primary')}${btn(state.favorites.includes(id)?'★ Saved':'☆ Save favorite','favorite',`data-id="${id}"`,'outline')}${btn('Add to grocery list','addgrocery',`data-id="${id}"`,'outline')}</div>`);}
function startWorkout(){const d=day();if(!d?.workout)return toast('Choose a strength day first.');if(doneWorkout(d.day))return history(d.day);const es=C.routine(state.profile,d.workout.light||d.workout.duration<25);if(!es.length)return toast('No compatible exercises. Review your limitations in Settings.');if(!session||session.day!==d.day)session={day:d.day,exercises:es.map(e=>({id:e.id,sets:Array.from({length:e.sets},()=>({reps:e.reps[0],weight:e.unit==='bodyweight'?0:C.progression(state.workouts,e,state.profile).weight,rpe:7}))}))};drawSession();}
function drawSession(){modal(`<p class="eyebrow">SESSION · ${dateLabel(session.day)}</p><h2>One set at a time.</h2><p class="muted">Warm up for 5 minutes with easy movement and practice reps. Effort 7–8 means roughly 2–3 good reps left. Save only sets you complete.</p><form id="workout-form">${session.exercises.map((entry,i)=>{const e=exercises.find(e=>e.id===entry.id),prog=C.progression(state.workouts,e,state.profile),prev=C.previousPerformance(state.workouts,e.id),alts=C.availableExercises(state.profile).filter(a=>a.pattern===e.pattern);return `<section class="session-exercise"><div class="section-head"><h3>${e.name}</h3><select aria-label="Substitute ${e.name}" data-substitute="${i}">${alts.map(a=>`<option value="${a.id}" ${a.id===e.id?'selected':''}>${a.name}</option>`).join('')}</select></div><p class="small">${e.cues}</p><p class="small muted">${e.reps.join('–')} reps · ${e.rest}s rest · weight ${e.unit}.<br>${prog.note}</p><p class="small">Previous: ${prev?prev.sets.map(s=>s.reps+' × '+s.weight+' kg').join(' / '):'No saved sets yet'}</p><div class="set-row set-heading"><span>Set</span><span>Reps</span><span>kg</span><span>Effort /10</span><span>Done</span></div>${entry.sets.map((s,j)=>`<div class="set-row"><span>${j+1}</span><input aria-label="${e.name} set ${j+1} reps" name="reps-${i}-${j}" type="number" min="1" max="100" required value="${s.reps}"><input aria-label="${e.name} set ${j+1} kg" name="weight-${i}-${j}" type="number" min="0" max="500" step=".25" required value="${s.weight}" ${e.unit==='bodyweight'?'readonly':''}><input aria-label="${e.name} set ${j+1} effort" name="rpe-${i}-${j}" type="number" min="1" max="10" required value="${s.rpe}"><input aria-label="${e.name} set ${j+1} completed" name="done-${i}-${j}" type="checkbox" ${s.done?'checked':''}></div>`).join('')}</section>`;}).join('')}<p class="small muted">You can finish early. Only checked sets are recorded. Completed history is never rewritten by plan edits.</p><button class="primary full" type="submit">Finish & save completed sets</button></form>`);}
function captureSession(){const f=new FormData($('#workout-form'));session.exercises.forEach((e,i)=>e.sets.forEach((s,j)=>{s.reps=Number(f.get(`reps-${i}-${j}`));s.weight=Number(f.get(`weight-${i}-${j}`));s.rpe=Number(f.get(`rpe-${i}-${j}`));s.done=f.has(`done-${i}-${j}`);}));}
function history(d){const w=doneWorkout(d);if(!w)return;modal(`<p class="eyebrow">COMPLETED · ${dateLabel(d)}</p><h2>Your session, saved.</h2>${w.exercises.map(entry=>`<section class="session-exercise"><h3>${exercises.find(e=>e.id===entry.id).name}</h3>${entry.sets.map((s,i)=>`<p>Set ${i+1} · ${s.reps} reps × ${s.weight} kg · effort ${s.rpe}/10</p>`).join('')}</section>`).join('')}<p class="small muted">Recorded ${new Date(w.saved).toLocaleString()}. Changes to your plan will not change this record.</p>`);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.');}catch{modal(`<h2>Copy this text</h2><p>Clipboard access is unavailable here. Select the text to copy it.</p><textarea rows="15" readonly>${esc(text)}</textarea>`);$('#modal textarea').select();}}
function download(text,name,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function checkin(){const d=selectedDay||today(),c=state.checkins.find(c=>c.day===d);modal(`<p class="eyebrow">WAKING DAY · ${dateLabel(d)}</p><h2>How are you doing?</h2><form id="checkin-form">${field('Day','day',d,'date','required')}${field('Weight in kg (optional)','weight',c?.weight||'','number','min="20" max="400" step=".1"')}<p class="small muted">If weighing, use similar conditions after waking. One reading is not a trend.</p><div class="form-grid">${select('Hunger','hunger',c?.hunger||3,[[1,'1 · Low'],[2,'2 · Mild'],[3,'3 · Manageable'],[4,'4 · Often hungry'],[5,'5 · Very hungry']])}${select('Energy','energy',c?.energy||3,[[1,'1 · Very low'],[2,'2 · Low'],[3,'3 · Okay'],[4,'4 · Good'],[5,'5 · High']])}</div><button class="primary" type="submit">Save check-in</button></form>`);}
function reminderSettings(){const p=state.profile;modal(`<h2>Your reminder preferences</h2><form id="reminder-form">${check('Workout alerts','workout',p.reminders.workout)}${p.reminders.meals.map((v,i)=>check('Meal '+(i+1)+' alerts','meal'+i,v)).join('')}<div class="form-grid">${field('Quiet hours start','quietStart',p.quietStart,'time','required')}${field('Quiet hours end','quietEnd',p.quietEnd,'time','required')}</div><p class="muted">Sleep and quiet hours suppress calendar events. After any schedule edit, replace the previous Afterhours calendar events with a fresh export. Imported events cannot be remotely changed by this local app.</p><button type="submit" class="primary">Save preferences</button></form>`);}
async function action(el){const a=el.dataset.action,id=el.dataset.id,d=el.dataset.day;
if(a==='close'){if($('#workout-form'))captureSession();close();}
if(a==='undo'&&undoState){const old=state;state=undoState;try{localStorage.setItem(KEY,JSON.stringify(state));undoState=old;render();toast('Change undone.');}catch{state=old;toast('Could not save undo.');}}
if(a==='setup'){draft=structuredClone(state.profile||C.defaults);step=0;setup();}
if(a==='setup-back'){if($('#setup-form')){try{readSetup($('#setup-form'));}catch{}}step--;setup();}
if(a==='acceptplan'){if(save('Plan saved. Your history is preserved.',()=>{const old=state.plan;state.profile=structuredClone(draft);state.plan=C.buildPlan(state.profile,C.wakingDay(state.profile),old,state.workouts);selectedDay=state.plan.start;session=null;})){close();view='today';location.hash='today';render();}}
if(a==='renew'){draft=structuredClone(state.profile);step=5;setup();}
if(a==='day'){selectedDay=d;render();}
if(a==='habit'||a==='recovery'){const dd=d||selectedDay||today();save('Daily essential updated.',()=>{state.habits[dd]||={};const key=a==='recovery'?'recovery':id;state.habits[dd][key]=!state.habits[dd][key];});}
if(a==='recipe')showRecipe(id,Number(el.dataset.servings)||1);
if(a==='favorite'){save('Favorite updated.',()=>{state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];});showRecipe(id,recipeServings);}
if(a==='copyrecipe')await copy(C.recipeText(activeRecipe,recipeServings,state.profile||C.defaults));
if(a==='addgrocery'){save('Recipe quantities added to the grocery list.',()=>state.extraGroceries.push({recipe:id,servings:recipeServings}));}
if(a==='clearextra')save('Extra grocery additions cleared.',()=>state.extraGroceries=[]);
if(a==='meal-tab'){mealTab=el.dataset.tab;render();}
if(a==='logmeal'){const m=state.plan.days.flatMap(d=>d.meals).find(m=>m.id===id);save('Meal log updated.',()=>{state.mealLogs=state.mealLogs.some(l=>l.id===id)?state.mealLogs.filter(l=>l.id!==id):[...state.mealLogs,{...m,day:d,nutrition:C.nutrition(C.recipe(m.recipe),m.servings,state.profile)}];});}
if(a==='swap'){const m=state.plan.days.flatMap(d=>d.meals).find(m=>m.id===id);modal(`<h2>Swap your meal</h2><p>Only recipes matching your allergies, preferences, kitchen, and prep time appear. Existing food logs keep their original nutrition.</p><form id="swap-form" data-id="${id}">${select('Recipe','recipe',m.recipe,C.allowedRecipes(state.profile).map(r=>[r.id,r.name]))}<button class="primary" type="submit">Save meal swap</button></form>`);}
if(a==='editmeal'){const m=state.plan.days.flatMap(d=>d.meals).find(m=>m.id===id);modal(`<h2>Meal time & portion</h2><form id="editmeal-form" data-id="${id}">${field('Time (Asia/Manila)','time',m.time,'time','required')}${field('Portions of the standard recipe','servings',m.servings,'number','min=".25" max="10" step=".25" required')}<p class="small muted">Nutrition, grocery quantities, and costs update together. Replace previously imported calendar alerts after changing times.</p><button class="primary" type="submit">Save changes</button></form>`);}
if(a==='reschedule'){const dd=state.plan.days.find(x=>x.day===(d||selectedDay||today()));modal(`<h2>Move this session</h2><p>This changes the existing workout, without creating another one. Overnight times stay with ${dateLabel(dd.day)}.</p><form id="reschedule-form" data-day="${dd.day}">${field('Workout time','time',dd.workout.time,'time','required')}<div class="button-row">${btn('02:30 backup','picktime','data-time="02:30"','outline')}${btn('09:30 after work','picktime','data-time="09:30"','outline')}</div><p class="small muted">Choose after-work training only when it suits your energy and sleep. Calendar alerts need a fresh export after edits.</p><button class="primary" type="submit">Move session</button></form>`);}
if(a==='picktime')$('#reschedule-form input').value=el.dataset.time;
if(a==='start')startWorkout();
if(a==='light'){save('Session intensity updated.',()=>{day().workout.light=!day().workout.light;session=null;});}
if(a==='history')history(d||selectedDay||today());
if(a==='checkin')checkin();
if(a==='food'){const dd=selectedDay||today(),f=state.foodLogs.find(l=>l.day===dd);modal(`<h2>Daily food record</h2><p>Enter the complete day's total from your own tracking, including logged planned meals. This record is separate from meal checkmarks, so it is never added twice.</p><form id="food-form">${field('Waking day','day',dd,'date','required')}${field('Total energy (kcal)','kcal',f?.kcal??'','number','min="0" max="20000" required')}${field('Total protein (g)','protein',f?.protein??'','number','min="0" max="1000" step=".1" required')}${check('This includes everything I ate in this waking day','complete',f?.complete)}<p class="small muted">Unchecked means partial, not zero. Weekly review requires enough complete days.</p><button class="primary" type="submit">Save food record</button></form>`);}
if(a==='acceptreview'||a==='declinereview'){const r=C.weeklyReview(state,today());if(a==='acceptreview'&&!r.delta)return;save('Review decision saved.',()=>{if(a==='acceptreview')state.plan.targets.kcal+=r.delta;state.review.push({day:today(),decision:a==='acceptreview'?'Accepted +100 kcal':'Kept targets unchanged'});});}
if(a==='export')download(JSON.stringify(state,null,2),'afterhours-backup-'+today()+'.json');
if(a==='recoveryexport')download(localStorage.getItem(KEY)||'','afterhours-recovery.json');
if(a==='persist'){const result=await navigator.storage?.persist?.();toast(result?'Persistent storage granted. Keep regular backups.':'Browser did not grant persistent storage. Keep regular backups.');}
if(a==='reminders')reminderSettings();
if(a==='calendar'){download(C.calendar(state),'afterhours-alerts.ics','text/calendar');toast('Calendar downloaded. Import into a dedicated calendar; replace old events after edits.');}
if(a==='copygroceries'){await copy('AFTERHOURS · 7-DAY GROCERIES\n'+C.groceries(state.plan.days.flatMap(d=>d.meals),state.profile,state.extraGroceries).map(g=>`${g.name}: ${g.packages} × ${g.pack} g — ${money(g.purchase)} est. (${Math.round(g.pantry)} g pantry used)`).join('\n'));}
if(a==='testnotification'){try{if(!('Notification'in window)||!('serviceWorker'in navigator))throw Error('Notifications unavailable. On iPhone, install with Safari’s Add to Home Screen first.');const perm=await Notification.requestPermission();if(perm!=='granted')throw Error('Permission not granted. Use device settings to enable it, or use calendar alerts.');const reg=await navigator.serviceWorker.ready;await reg.showNotification('Afterhours · Test notification',{body:'Immediate device test. Scheduled background push is not connected.',icon:'/icon-192.png',tag:'afterhours-test'});toast('Test submitted to your device. Confirm that you saw it; delivery is not verified.');render();}catch(e){toast(e.message);}}
if(a==='delete')modal(`<h2>Delete local records?</h2><p>This removes your plan, history, journal, and preferences from this browser. Your backup files and imported calendar alerts remain.</p><form id="delete-form">${field('Type DELETE to confirm','confirm','','text','required pattern="DELETE"')}<button class="danger-button" type="submit">Delete records</button></form>`);
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();Promise.resolve(action(el)).catch(err=>toast(err.message));}});
document.addEventListener('submit',e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const data=new FormData(f),get=n=>data.get(n);try{
if(f.id==='setup-form'){readSetup(f);step++;setup();return;}
if(f.id==='workout-form'){captureSession();const es=session.exercises.map(e=>({id:e.id,sets:e.sets.filter(s=>s.done).map(({done,...s})=>s)})).filter(e=>e.sets.length);if(!es.length)throw Error('Check at least one completed set before saving.');if(doneWorkout(session.day))throw Error('This waking day already has a completed session.');save('Workout saved. +30 XP',()=>state.workouts.push({day:session.day,exercises:es,saved:new Date().toISOString()}));session=null;close();return;}
if(f.id==='reschedule-form'){const dd=state.plan.days.find(d=>d.day===f.dataset.day),s=C.settingsFor(state.profile,dd.day);if(C.isAsleep(get('time'),s))throw Error('That time falls inside your sleep window. Choose a time while awake.');save('The same session has been moved. Replace old calendar alerts.',()=>state.plan=C.reschedule(state.plan,dd.day,get('time')));close();return;}
if(f.id==='swap-form'){save('Meal swapped. Nutrition and groceries recalculated.',()=>state.plan=C.swapMeal(state.plan,state.profile,f.dataset.id,get('recipe')));close();return;}
if(f.id==='editmeal-form'){const dd=state.plan.days.find(d=>d.meals.some(m=>m.id===f.dataset.id));if(C.isAsleep(get('time'),C.settingsFor(state.profile,dd.day)))throw Error('This meal falls inside your sleep window.');save('Meal updated. Replace old calendar alerts.',()=>{const m=dd.meals.find(m=>m.id===f.dataset.id);m.time=get('time');m.servings=Number(get('servings'));});close();return;}
if(f.id==='checkin-form'){if(get('day')>today())throw Error('Check-ins cannot be dated in the future.');save('Check-in saved.',()=>{state.checkins=state.checkins.filter(c=>c.day!==get('day'));state.checkins.push({day:get('day'),weight:get('weight')?Number(get('weight')):null,hunger:Number(get('hunger')),energy:Number(get('energy'))});state.checkins.sort((a,b)=>a.day.localeCompare(b.day));});close();return;}
if(f.id==='food-form'){save('Daily food record saved.',()=>{state.foodLogs=state.foodLogs.filter(l=>l.day!==get('day'));state.foodLogs.push({day:get('day'),kcal:Number(get('kcal')),protein:Number(get('protein')),complete:data.has('complete')});});close();return;}
if(f.id==='journal-form'){save('Note saved.',()=>state.journal.push({day:selectedDay||today(),text:get('text').trim()}));return;}
if(f.id==='reminder-form'){save('Reminder preferences saved. Replace old calendar alerts.',()=>{state.profile.reminders={workout:data.has('workout'),meals:[0,1,2].map(i=>data.has('meal'+i))};state.profile.quietStart=get('quietStart');state.profile.quietEnd=get('quietEnd');});close();return;}
if(f.id==='prices-form'){save('Pantry and prices saved. Grocery totals updated.',()=>{for(const [id,i]of Object.entries(ingredients)){state.profile.pantry[id]=Number(get('pantry-'+id));const price=Number(get('price-'+id)),pack=Number(get('pack-'+id)),source=get('source-'+id);const old=state.profile.prices[id];if(price!==(old?.price??i.price)||pack!==(old?.pack??i.pack)||source!==(old?.source||'Unverified planning estimate'))state.profile.prices[id]={price,pack,source,date:today()};}});return;}
if(f.id==='delete-form'&&get('confirm')==='DELETE'){localStorage.removeItem(KEY);state=C.fresh();storageError='';selectedDay='';undoState=null;session=null;render();close();toast('Local records deleted. Remove calendar events separately.');return;}
if(f.id==='import-form'){save('Backup imported.',()=>{state=JSON.parse(f.dataset.backup);selectedDay='';session=null;});close();return;}
}catch(err){if(f.id==='setup-form')$('#setup-error').textContent=err.message;else toast(err.message);}});
document.addEventListener('change',async e=>{if(e.target.id==='recipe-servings'){const n=Number(e.target.value);if(n>=.25&&n<=10)showRecipe(activeRecipe.id,n);}
if(e.target.dataset.substitute!==undefined){const index=Number(e.target.dataset.substitute),id=e.target.value;captureSession();const ex=exercises.find(x=>x.id===id);session.exercises[index]={id,sets:Array.from({length:session.exercises[index].sets.length},()=>({reps:ex.reps[0],weight:0,rpe:7}))};drawSession();}
if(e.target.id==='import-file'){try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('Backup exceeds the 10 MB limit.');const x=C.validateBackup(JSON.parse(await file.text()));modal(`<h2>Replace records with this backup?</h2><p>${x.workouts.length} sessions, ${x.checkins.length} check-ins, ${x.journal.length} notes. Export your current records first if needed.</p><form id="import-form"><button class="primary" type="submit">Import & replace</button></form>`);$('#import-form').dataset.backup=JSON.stringify(x);}catch(err){toast('Import rejected: '+err.message);}}
});
window.addEventListener('hashchange',()=>{view=location.hash.slice(1)||'today';render();window.scrollTo(0,0);});
window.addEventListener('online',render);window.addEventListener('offline',render);
window.addEventListener('storage',e=>{if(e.key===KEY){toast('Records changed in another tab. Reload to use the latest version.');}});
render();
if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').then(()=>{navigator.serviceWorker.ready.then(()=>{const el=$('#offline-status');if(el)el.textContent='App cache ready.';});}).catch(()=>toast('Offline cache could not be installed. Keep this app online and retry.'));}
